# Voice-Controlled Light System - Raspberry Pi + SpeechRecognition + GPIO Relay
import speech_recognition as sr
import RPi.GPIO as GPIO
import time, paho.mqtt.client as mqtt

BROKER      = "localhost"
TOPIC_STATE = "home/lights/state"
RELAY_PINS  = {"living": 17, "bedroom": 27, "kitchen": 22}
light_state = {room: False for room in RELAY_PINS}

GPIO.setmode(GPIO.BCM)
for pin in RELAY_PINS.values():
    GPIO.setup(pin, GPIO.OUT, initial=GPIO.HIGH)

client = mqtt.Client("voice_lights")
client.connect(BROKER); client.loop_start()
rec = sr.Recognizer(); mic = sr.Microphone()

COMMANDS = {
    "living on":   ("living",  True),  "living off":  ("living",  False),
    "bedroom on":  ("bedroom", True),  "bedroom off": ("bedroom", False),
    "kitchen on":  ("kitchen", True),  "kitchen off": ("kitchen", False),
    "all on":      ("all",     True),  "all off":     ("all",     False),
}

def set_light(room, state):
    if room == "all":
        for r in RELAY_PINS: set_light(r, state)
        return
    GPIO.output(RELAY_PINS[room], GPIO.LOW if state else GPIO.HIGH)
    light_state[room] = state
    print(f"[Light] {room} -> {'ON' if state else 'OFF'}")
    client.publish(TOPIC_STATE, str(light_state))

def process(text):
    text = text.lower()
    for trigger, (room, state) in COMMANDS.items():
        if trigger in text:
            set_light(room, state); return
    print("Unrecognized:", text)

print("Voice Light System - listening...")
with mic as src: rec.adjust_for_ambient_noise(src, duration=1)
while True:
    try:
        with mic as src:
            audio = rec.listen(src, timeout=5, phrase_time_limit=4)
        text = rec.recognize_google(audio)
        print("Heard:", text); process(text)
    except sr.WaitTimeoutError: pass
    except sr.UnknownValueError: print("(inaudible)")
    except KeyboardInterrupt: GPIO.cleanup(); break

