// Automated Window Blinds - NodeMCU ESP8266 + Stepper 28BYJ-48 + LDR + MQTT
#include <ESP8266WiFi.h>
#include <PubSubClient.h>
#include <AccelStepper.h>

const char* SSID   = "HOME_NET";
const char* PWD    = "HOME_PASS";
const char* BROKER = "broker.hivemq.com";

#define LDR_PIN           A0
#define STEPS_FULL_TRAVEL 2048

AccelStepper stepper(AccelStepper::HALF4WIRE, D1, D3, D2, D4);
WiFiClient wf; PubSubClient mqtt(wf);
int pos = 0; bool autoMode = true;

void moveTo(int target) {
    stepper.moveTo(target);
    while (stepper.distanceToGo() != 0) stepper.run();
    pos = target;
}

void onMessage(char* topic, byte* payload, unsigned int len) {
    String msg = String((char*)payload).substring(0, len);
    if (msg == "open")        { autoMode = false; moveTo(0); }
    else if (msg == "close")  { autoMode = false; moveTo(STEPS_FULL_TRAVEL); }
    else if (msg == "auto")   { autoMode = true; }
    else if (msg.startsWith("set:")) {
        int pct = msg.substring(4).toInt();
        moveTo(map(pct, 0, 100, 0, STEPS_FULL_TRAVEL));
    }
}

void setup() {
    stepper.setMaxSpeed(500); stepper.setAcceleration(200);
    WiFi.begin(SSID, PWD);
    while (WiFi.status() != WL_CONNECTED) delay(300);
    mqtt.setServer(BROKER, 1883); mqtt.setCallback(onMessage);
    mqtt.connect("blinds"); mqtt.subscribe("home/blinds/cmd");
}

void loop() {
    mqtt.loop();
    if (autoMode) {
        int ldr = analogRead(LDR_PIN);
        if (ldr > 750 && pos == 0)                    moveTo(STEPS_FULL_TRAVEL);
        else if (ldr < 300 && pos == STEPS_FULL_TRAVEL) moveTo(0);
    }
    mqtt.publish("home/blinds/state",
        ("{\"pos\":" + String(pos) + ",\"ldr\":" + String(analogRead(LDR_PIN)) + "}").c_str());
    delay(3000);
}

