# Home Energy Dashboard - Raspberry Pi + PZEM-004T + Flask real-time UI
from flask import Flask, jsonify, render_template_string
import threading, time, serial, paho.mqtt.client as mqtt

SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE   = 9600
BROKER      = "localhost"
app         = Flask(__name__)
readings    = {"voltage": 0, "current": 0, "power": 0, "energy": 0, "pf": 0, "freq": 0}
history     = []

def read_pzem():
    try:
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1) as ser:
            # PZEM-004T read command
            cmd = bytes([0xF8, 0x04, 0x00, 0x00, 0x00, 0x0A, 0x64, 0x64])
            ser.write(cmd); raw = ser.read(25)
            if len(raw) >= 25:
                return {
                    "voltage": ((raw[3] << 8) | raw[4]) / 10.0,
                    "current": ((raw[5] << 8) | raw[6]) / 1000.0,
                    "power":   ((raw[9] << 8) | raw[10]) / 10.0,
                    "energy":  ((raw[13] << 8) | raw[14]),
                    "freq":    ((raw[17] << 8) | raw[18]) / 10.0,
                    "pf":      ((raw[19] << 8) | raw[20]) / 100.0,
                }
    except Exception as e:
        print("Serial error:", e)
        import random
        return {"voltage": round(random.uniform(218, 232), 1),
                "current": round(random.uniform(0.5, 8.0), 2),
                "power":   round(random.uniform(100, 1800), 1),
                "energy":  round(random.uniform(0, 50), 2),
                "freq":    50.0, "pf": round(random.uniform(0.85, 0.99), 2)}

DASHBOARD = (
    "<!DOCTYPE html><html><head><title>Energy Dashboard</title>"
    "<meta http-equiv='refresh' content='5'>"
    "<style>body{font-family:sans-serif;background:#111;color:#eee;text-align:center}"
    ".card{display:inline-block;background:#222;border-radius:12px;padding:20px 30px;margin:10px}"
    ".val{font-size:2em;color:orange}</style></head><body>"
    "<h2>Home Energy Dashboard</h2>"
    "{% for k,v in data.items() %}<div class='card'><div>{{k.upper()}}</div>"
    "<div class='val'>{{v}}</div></div>{% endfor %}</body></html>"
)

@app.route("/")
def index(): return render_template_string(DASHBOARD, data=readings)

@app.route("/api")
def api(): return jsonify(readings)

def poller():
    mc = mqtt.Client("energy_dash"); mc.connect(BROKER); mc.loop_start()
    while True:
        r = read_pzem()
        if r:
            readings.update(r); history.append({**r, "ts": time.time()})
            if len(history) > 60: history.pop(0)
            mc.publish("home/energy/readings", str(r))
        time.sleep(5)

threading.Thread(target=poller, daemon=True).start()
app.run(host="0.0.0.0", port=5000)

