// Smart Smoke & Gas Detector - NodeMCU + MQ2 + MQ7 + Buzzer + GSM SMS Alert
#include <ESP8266WiFi.h>
#include <PubSubClient.h>
#include <SoftwareSerial.h>

const char* SSID   = "HOME_NET";
const char* PWD    = "HOME_PASS";
const char* BROKER = "broker.hivemq.com";
const char* PHONE  = "+919876543210";

#define MQ2_PIN    A0
#define BUZZER     D5
#define RED_LED    D6
#define GREEN_LED  D7
#define GSM_RX     D2
#define GSM_TX     D3
#define SMOKE_THRESHOLD 400
#define ALERT_COOLDOWN  60000UL

SoftwareSerial gsm(GSM_RX, GSM_TX);
WiFiClient wf; PubSubClient mqtt(wf);
unsigned long lastAlert = 0;

void sendSMS(const char* msg) {
    gsm.print("AT+CMGF=1\r"); delay(500);
    gsm.print("AT+CMGS=\""); gsm.print(PHONE); gsm.print("\"\r"); delay(500);
    gsm.print(msg); gsm.write(26); delay(3000);
}

void setup() {
    Serial.begin(115200); gsm.begin(9600);
    pinMode(BUZZER, OUTPUT); pinMode(RED_LED, OUTPUT); pinMode(GREEN_LED, OUTPUT);
    WiFi.begin(SSID, PWD);
    while (WiFi.status() != WL_CONNECTED) delay(300);
    mqtt.setServer(BROKER, 1883); mqtt.connect("smoke_det");
    digitalWrite(GREEN_LED, HIGH);
    Serial.println("Smoke & Gas Detector READY");
}

void loop() {
    if (!mqtt.connected()) mqtt.connect("smoke_det");
    mqtt.loop();
    int mq2    = analogRead(MQ2_PIN);
    bool danger = (mq2 > SMOKE_THRESHOLD);
    mqtt.publish("home/smoke/reading",
        ("{\"mq2\":" + String(mq2) + ",\"alert\":" + String(danger) + "}").c_str());
    if (danger) {
        digitalWrite(RED_LED, HIGH); digitalWrite(GREEN_LED, LOW);
        digitalWrite(BUZZER, HIGH);
        if (millis() - lastAlert > ALERT_COOLDOWN) {
            sendSMS("ALERT! Smoke/Gas detected at home!");
            mqtt.publish("home/smoke/alert", "{\"level\":\"DANGER\"}");
            lastAlert = millis();
        }
    } else {
        digitalWrite(RED_LED, LOW); digitalWrite(GREEN_LED, HIGH);
        digitalWrite(BUZZER, LOW);
    }
    delay(2000);
}

