// Smart Garden Irrigation - NodeMCU + Soil Moisture + DHT11 + Water Pump Relay
#include <ESP8266WiFi.h>
#include <PubSubClient.h>
#include <DHT.h>

const char* SSID   = "HOME_NET";
const char* PWD    = "HOME_PASS";
const char* BROKER = "broker.hivemq.com";

#define SOIL_PIN      A0
#define DHT_PIN       D4
#define PUMP_RELAY    D1
#define DRY_THRESHOLD 600
#define PUMP_DURATION 10000UL

DHT dht(DHT_PIN, DHT11);
WiFiClient wf; PubSubClient mqtt(wf);
bool autoMode = true, pumping = false;
unsigned long pumpStart = 0;

void onMsg(char* t, byte* p, unsigned int l) {
    String m((char*)p, l);
    if (m == "pump_on")  { digitalWrite(PUMP_RELAY, LOW);  pumping = true; pumpStart = millis(); }
    if (m == "pump_off") { digitalWrite(PUMP_RELAY, HIGH); pumping = false; }
    if (m == "auto_on")  autoMode = true;
    if (m == "auto_off") autoMode = false;
}

void setup() {
    Serial.begin(115200); dht.begin();
    pinMode(PUMP_RELAY, OUTPUT); digitalWrite(PUMP_RELAY, HIGH);
    WiFi.begin(SSID, PWD); while (!WiFi.isConnected()) delay(300);
    mqtt.setServer(BROKER, 1883); mqtt.setCallback(onMsg);
    mqtt.connect("garden"); mqtt.subscribe("home/garden/cmd");
}

void loop() {
    mqtt.loop();
    if (pumping && millis() - pumpStart > PUMP_DURATION) {
        digitalWrite(PUMP_RELAY, HIGH); pumping = false;
    }
    int   soil = analogRead(SOIL_PIN);
    float t    = dht.readTemperature();
    float h    = dht.readHumidity();
    int   pct  = map(soil, 1023, 0, 0, 100);
    if (autoMode && soil > DRY_THRESHOLD && !pumping) {
        digitalWrite(PUMP_RELAY, LOW); pumping = true; pumpStart = millis();
    }
    mqtt.publish("home/garden/state",
        ("{\"moisture_pct\":" + String(pct) + ",\"temp\":" + String(t) +
         ",\"humidity\":" + String(h) + ",\"pump\":" + String(pumping) + "}").c_str());
    delay(5000);
}

