// Wi-Fi Smart Plug - ESP8266 + ACS712 Current Sensor + MQTT + Energy Logging
#include <ESP8266WiFi.h>
#include <PubSubClient.h>
#include <ArduinoJson.h>

const char* SSID   = "HOME_NET";
const char* PWD    = "HOME_PASS";
const char* BROKER = "broker.hivemq.com";
const char* DEV_ID = "smart_plug_01";

#define RELAY_PIN  D1
#define ACS_PIN    A0
#define LED_PIN    D7
#define BTN_PIN    D2
#define MAINS_V    230.0f
#define ACS_SENS   0.185f     // V/A for ACS712-5A

WiFiClient wf; PubSubClient mqtt(wf);
bool plugOn = false; float totalKWh = 0; unsigned long lastMs = 0;

float readCurrent() {
    float v = analogRead(ACS_PIN) * (3.3f / 1023.0f);
    return fabsf((v - 1.65f) / ACS_SENS);
}

void setPlug(bool on) {
    plugOn = on;
    digitalWrite(RELAY_PIN, on ? LOW : HIGH);
    digitalWrite(LED_PIN,   on ? HIGH : LOW);
    mqtt.publish("home/plug/state", on ? "ON" : "OFF");
}

void onMsg(char* topic, byte* payload, unsigned int len) {
    String m((char*)payload, len);
    if (m == "ON" || m == "1")  setPlug(true);
    if (m == "OFF" || m == "0") setPlug(false);
    if (m == "TOGGLE")          setPlug(!plugOn);
}

void setup() {
    Serial.begin(115200);
    pinMode(RELAY_PIN, OUTPUT); pinMode(LED_PIN, OUTPUT); pinMode(BTN_PIN, INPUT_PULLUP);
    setPlug(false);
    WiFi.begin(SSID, PWD); while (!WiFi.isConnected()) delay(300);
    mqtt.setServer(BROKER, 1883); mqtt.setCallback(onMsg);
    mqtt.connect(DEV_ID); mqtt.subscribe("home/plug/cmd");
    lastMs = millis();
}

void loop() {
    if (!mqtt.connected()) { mqtt.connect(DEV_ID); mqtt.subscribe("home/plug/cmd"); }
    mqtt.loop();
    if (digitalRead(BTN_PIN) == LOW) { setPlug(!plugOn); delay(400); }
    float i = plugOn ? readCurrent() : 0;
    float p = i * MAINS_V;
    totalKWh += p * ((millis() - lastMs) / 3600000.0f) / 1000.0f;
    lastMs = millis();
    StaticJsonDocument<128> doc;
    doc["state"] = plugOn ? "ON" : "OFF";
    doc["current_a"] = round(i * 100) / 100.0;
    doc["power_w"]   = round(p);
    doc["kwh"]       = round(totalKWh * 1000) / 1000.0;
    char buf[128]; serializeJson(doc, buf);
    mqtt.publish("home/plug/data", buf);
    delay(3000);
}

