# Home Intrusion Detection - Raspberry Pi + PIR + Pi Camera + Telegram Alert
import RPi.GPIO as GPIO, time, requests, paho.mqtt.client as mqtt
from picamera2 import Picamera2

BROKER      = "localhost"
BOT_TOKEN   = "YOUR_TELEGRAM_TOKEN"
CHAT_ID     = "YOUR_CHAT_ID"
PIR_PINS    = {"front_door": 17, "back_door": 27, "living_room": 22}
COOLDOWN    = 30

GPIO.setmode(GPIO.BCM)
for pin in PIR_PINS.values(): GPIO.setup(pin, GPIO.IN)

camera  = Picamera2()
camera.configure(camera.create_still_configuration())
camera.start()

client  = mqtt.Client("intrusion")
client.connect(BROKER); client.loop_start()
last_alert = {}

def capture_photo():
    path = "/tmp/intruder.jpg"
    camera.capture_file(path); return path

def send_telegram(zone, photo_path):
    url = f"https://api.telegram.org/bot{BOT_TOKEN}/sendPhoto"
    with open(photo_path, "rb") as f:
        requests.post(url, data={"chat_id": CHAT_ID,
            "caption": f"INTRUSION at {zone}!"}, files={"photo": f})

def motion_detected(zone):
    now = time.time()
    if now - last_alert.get(zone, 0) < COOLDOWN: return
    last_alert[zone] = now
    print(f"[ALERT] Motion at {zone}")
    photo = capture_photo()
    send_telegram(zone, photo)
    client.publish("home/intrusion/alert", f'{{"zone":"{zone}","ts":{now}}}')

def cb(pin):
    for zone, p in PIR_PINS.items():
        if p == pin: motion_detected(zone)

for zone, pin in PIR_PINS.items():
    GPIO.add_event_detect(pin, GPIO.RISING, callback=cb, bouncetime=2000)

print("Intrusion System ARMED")
try:
    while True:
        states = {z: GPIO.input(p) for z, p in PIR_PINS.items()}
        client.publish("home/intrusion/status", str(states)); time.sleep(10)
except KeyboardInterrupt:
    camera.stop(); GPIO.cleanup()

