// Home Water Leak Detector - ESP8266 + Water Sensor + Solenoid Valve + Telegram
#include <ESP8266WiFi.h>
#include <UniversalTelegramBot.h>
#include <WiFiClientSecure.h>
#include <PubSubClient.h>

const char* SSID    = "HOME_NET";
const char* PWD     = "HOME_PASS";
const char* BROKER  = "broker.hivemq.com";
const char* TOKEN   = "YOUR_TOKEN";
const char* CHAT_ID = "YOUR_CHAT_ID";

#define SENSOR_PIN  A0
#define VALVE_RELAY D1
#define BUZZER_PIN  D5
#define LEAK_THRESH 500
#define ALERT_CD    60000UL

WiFiClientSecure ssl; UniversalTelegramBot bot(TOKEN, ssl);
WiFiClient wf;        PubSubClient mqtt(wf);
unsigned long lastAlert = 0;

void setup() {
    Serial.begin(115200);
    pinMode(VALVE_RELAY, OUTPUT); digitalWrite(VALVE_RELAY, LOW);
    pinMode(BUZZER_PIN,  OUTPUT);
    ssl.setInsecure();
    WiFi.begin(SSID, PWD); while (!WiFi.isConnected()) delay(300);
    mqtt.setServer(BROKER, 1883); mqtt.connect("leak_detect");
}

void loop() {
    mqtt.loop();
    int  val  = analogRead(SENSOR_PIN);
    bool leak = (val > LEAK_THRESH);
    if (leak) {
        digitalWrite(VALVE_RELAY, HIGH);
        digitalWrite(BUZZER_PIN,  HIGH);
        if (millis() - lastAlert > ALERT_CD) {
            bot.sendMessage(CHAT_ID, "WATER LEAK DETECTED! Valve closed.", "");
            mqtt.publish("home/leak/alert", "{\"status\":\"LEAK\"}");
            lastAlert = millis();
        }
    } else {
        digitalWrite(BUZZER_PIN, LOW);
    }
    mqtt.publish("home/leak/state",
        ("{\"sensor\":" + String(val) + ",\"leak\":" + String(leak) + "}").c_str());
    delay(2000);
}

