// Automated Curtain Controller - ESP8266 + Stepper 28BYJ-48 + LDR + MQTT
#include <ESP8266WiFi.h>
#include <PubSubClient.h>
#include <AccelStepper.h>
AccelStepper stepper(AccelStepper::HALF4WIRE, D1, D3, D2, D4);
WiFiClient wf; PubSubClient mqtt(wf);
#define LDR A0
#define STEPS 2048
void onMsg(char* t, byte* p, unsigned int l) {
    String m((char*)p, l);
    if (m == "open") stepper.moveTo(0);
    if (m == "close") stepper.moveTo(STEPS);
}
void setup() {
    stepper.setMaxSpeed(500); stepper.setAcceleration(200);
    WiFi.begin("HOME_NET","HOME_PASS");
    while (!WiFi.isConnected()) delay(300);
    mqtt.setServer("broker.hivemq.com", 1883); mqtt.setCallback(onMsg);
    mqtt.connect("curtain"); mqtt.subscribe("home/curtain/cmd");
}
void loop() {
    mqtt.loop(); stepper.run();
    int ldr = analogRead(LDR);
    if (ldr > 700 && stepper.currentPosition() != STEPS) stepper.moveTo(STEPS);
    if (ldr < 300 && stepper.currentPosition() != 0)     stepper.moveTo(0);
    mqtt.publish("home/curtain/state",
        ("{\"ldr\":" + String(ldr) + ",\"pos\":" + String(stepper.currentPosition()) + "}").c_str());
    delay(3000);
}

