// Room Occupancy Sensor - ESP8266 + PIR + HC-SR04 + MQTT + Auto Light
#include <ESP8266WiFi.h>
#include <PubSubClient.h>
WiFiClient wf; PubSubClient mqtt(wf);
#define PIR_PIN D2
#define TRIG    D5
#define ECHO    D6
#define LIGHT   D1
#define TIMEOUT 300000UL
bool occupied = false; unsigned long lastMotion = 0;

float dist() {
    digitalWrite(TRIG, LOW); delayMicroseconds(2);
    digitalWrite(TRIG, HIGH); delayMicroseconds(10); digitalWrite(TRIG, LOW);
    return pulseIn(ECHO, HIGH) / 58.0;
}
void setup() {
    Serial.begin(115200);
    pinMode(PIR_PIN, INPUT); pinMode(TRIG, OUTPUT);
    pinMode(ECHO, INPUT);    pinMode(LIGHT, OUTPUT);
    WiFi.begin("HOME_NET", "HOME_PASS"); while (!WiFi.isConnected()) delay(300);
    mqtt.setServer("broker.hivemq.com", 1883); mqtt.connect("occupancy");
}
void loop() {
    mqtt.loop();
    bool motion = digitalRead(PIR_PIN);
    float d     = dist();
    if (motion || d < 150) { lastMotion = millis(); occupied = true; }
    if (occupied && millis() - lastMotion > TIMEOUT) occupied = false;
    digitalWrite(LIGHT, occupied ? LOW : HIGH);
    mqtt.publish("home/occupancy",
        ("{\"occupied\":" + String(occupied) + ",\"dist_cm\":" + String(d) + "}").c_str());
    delay(1000);
}

