// IoT Power Strip - ESP8266 + 4-Channel Relay + Per-Outlet MQTT Control
#include <ESP8266WiFi.h>
#include <PubSubClient.h>
WiFiClient wf; PubSubClient mqtt(wf);
const int RELAY_PINS[4] = {D1, D2, D3, D4};
bool states[4] = {false, false, false, false};

void setOutlet(int n, bool on) {
    if (n < 0 || n >= 4) return;
    states[n] = on;
    digitalWrite(RELAY_PINS[n], on ? LOW : HIGH);
    Serial.printf("Outlet %d: %s\n", n, on ? "ON" : "OFF");
}
// Message format: "0:ON", "1:OFF", "ALL:OFF"
void onMsg(char* t, byte* p, unsigned int l) {
    String m((char*)p, l);
    if (m.startsWith("ALL")) { bool s = m.endsWith("ON"); for (int i=0;i<4;i++) setOutlet(i,s); return; }
    int n = m.charAt(0) - '0'; bool s = m.substring(2) == "ON";
    setOutlet(n, s);
}
void setup() {
    Serial.begin(115200);
    for (int i = 0; i < 4; i++) { pinMode(RELAY_PINS[i], OUTPUT); setOutlet(i, false); }
    WiFi.begin("HOME_NET","HOME_PASS"); while (!WiFi.isConnected()) delay(300);
    mqtt.setServer("broker.hivemq.com", 1883); mqtt.setCallback(onMsg);
    mqtt.connect("power_strip"); mqtt.subscribe("home/strip/cmd");
}
void loop() {
    mqtt.loop();
    String j = "{";
    for (int i = 0; i < 4; i++) j += "\"o" + String(i) + "\":" + String(states[i]) + (i<3?",":"");
    j += "}";
    mqtt.publish("home/strip/state", j.c_str());
    delay(3000);
}

