// Smart Aquarium Controller - ESP8266 + DS18B20 + pH Sensor + Relay Bank
#include <ESP8266WiFi.h>
#include <PubSubClient.h>
#include <OneWire.h>
#include <DallasTemperature.h>
OneWire ow(D4); DallasTemperature ds(&ow);
WiFiClient wf; PubSubClient mqtt(wf);
#define PH_PIN    A0
#define HEATER    D1
#define LIGHT     D2
#define PUMP      D3
#define TEMP_MIN  24.0f
#define TEMP_MAX  28.0f
float readPH() { return analogRead(PH_PIN) * 14.0f / 1023.0f; }
void setup() {
    Serial.begin(115200); ds.begin();
    pinMode(HEATER, OUTPUT); pinMode(LIGHT, OUTPUT); pinMode(PUMP, OUTPUT);
    digitalWrite(PUMP, LOW);  // always circulate
    WiFi.begin("HOME_NET","HOME_PASS"); while (!WiFi.isConnected()) delay(300);
    mqtt.setServer("broker.hivemq.com", 1883); mqtt.connect("aquarium");
}
void loop() {
    mqtt.loop(); ds.requestTemperatures();
    float t  = ds.getTempCByIndex(0);
    float ph = readPH();
    digitalWrite(HEATER, t < TEMP_MIN ? LOW : HIGH);
    int hr = millis() / 3600000 % 24;
    digitalWrite(LIGHT, (hr >= 7 && hr < 22) ? LOW : HIGH);
    mqtt.publish("home/aquarium/state",
        ("{\"temp\":" + String(t) + ",\"ph\":" + String(ph,1) +
         ",\"heater_on\":" + String(t < TEMP_MIN) + "}").c_str());
    delay(10000);
}

