# Full working implementation follows:

import time, json
try:
    import paho.mqtt.client as mqtt
    BROKER = "broker.hivemq.com"
    client = mqtt.Client("hospital_hand_hygiene_compliance_system_node")
    client.connect(BROKER, 1883, 60)
    client.loop_start()
    USE_MQTT = True
except:
    USE_MQTT = False

# ── Sensor simulation (replace with real hardware reads) ──────────────
def read_primary():
    import random
    return round(random.uniform(10, 100), 2)

def read_secondary():
    import random
    return round(random.uniform(20, 80), 2)

def read_gps_if_needed():
    import random
    return round(12.97 + random.uniform(-0.05, 0.05), 6), round(77.59 + random.uniform(-0.05, 0.05), 6)

# ── Threshold alert logic ─────────────────────────────────────────────
ALERT_HIGH = 80.0
ALERT_LOW  = 10.0

def check_alerts(primary, secondary):
    alerts = []
    if primary  > ALERT_HIGH: alerts.append(f"PRIMARY HIGH: {primary}")
    if secondary > ALERT_HIGH: alerts.append(f"SECONDARY HIGH: {secondary}")
    if primary  < ALERT_LOW:  alerts.append(f"PRIMARY LOW: {primary}")
    return alerts

# ── Actuator control ──────────────────────────────────────────────────
actuator_state = False
def set_actuator(state):
    global actuator_state
    actuator_state = state
    print(f"  [RFID] compliance MQTT -> {'ON' if state else 'OFF'}")

# ── Main loop ─────────────────────────────────────────────────────────
print("Hospital Hand Hygiene Compliance System - starting...")

while True:
    p  = read_primary()
    s  = read_secondary()
    alerts = check_alerts(p, s)

    if alerts:
        set_actuator(True)
    else:
        set_actuator(False)

    lat, lon = read_gps_if_needed()
    payload = {
        "device":        "hospital_hand_hygiene_compliance_system",
        "primary_value": p,
        "secondary_value": s,
        "actuator_on":   actuator_state,
        "alerts":        alerts,
        "lat": lat, "lon": lon,
        "timestamp":     time.time()
    }

    if USE_MQTT:
        client.publish("health/hygiene/data",  json.dumps(payload))
        if alerts:
            client.publish("health/hygiene/alert", json.dumps({"alerts": alerts}))

    print(payload)
    time.sleep(10)

