    if primary  > ALERT_HIGH: alerts.append(f"PRIMARY HIGH: {primary}")
    if secondary > ALERT_HIGH: alerts.append(f"SECONDARY HIGH: {secondary}")
    if primary  < ALERT_LOW:  alerts.append(f"PRIMARY LOW: {primary}")
    return alerts

