def set_actuator(state):
    global actuator_state
    actuator_state = state
    print(f"  [GPS] map alert -> {'ON' if state else 'OFF'}")

# ── Main loop ─────────────────────────────────────────────────────────
print("Land Subsidence Detection System - starting...")

while True:
    p  = read_primary()
    s  = read_secondary()
    alerts = check_alerts(p, s)

    if alerts:
        set_actuator(True)
    else:
        set_actuator(False)

    lat, lon = read_gps_if_needed()
    payload = {
        "device":        "land_subsidence_detection_system",
        "primary_value": p,
        "secondary_value": s,
        "actuator_on":   actuator_state,
        "alerts":        alerts,
        "lat": lat, "lon": lon,
        "timestamp":     time.time()
    }

    if USE_MQTT:
        client.publish("env/subsidence/data",  json.dumps(payload))
        if alerts:
            client.publish("env/subsidence/alert", json.dumps({"alerts": alerts}))

    print(payload)
    time.sleep(10)

