actuator_state = False
def set_actuator(state):
    global actuator_state
    actuator_state = state
    print(f"  [RELAY] door relay -> {'ON' if state else 'OFF'}")

# ── Main loop ─────────────────────────────────────────────────────────
print("Facial Recognition Access Control - starting...")

while True:
    p  = read_primary()
    s  = read_secondary()
    alerts = check_alerts(p, s)

    if alerts:
        set_actuator(True)
    else:
        set_actuator(False)

    lat, lon = read_gps_if_needed()
    payload = {
        "device":        "facial_recognition_access_control",
