        "actuator_on":   actuator_state,
        "alerts":        alerts,
        "lat": lat, "lon": lon,
        "timestamp":     time.time()
    }

    if USE_MQTT:
        client.publish("security/facerec/data",  json.dumps(payload))
        if alerts:
            client.publish("security/facerec/alert", json.dumps({"alerts": alerts}))

    print(payload)
    time.sleep(10)

